3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"sync"
8	)
9	
10	// State is the complete database. It is small enough to live in memory and to be
11	// rewritten atomically as one JSON document after every mutation, which is what
12	// replaces a real database driver in this standard-library-only build.
13	type State struct {
14		// Spans is trace id -> span id -> span, giving both lookups in one place.
15		Spans       map[string]map[string]*SpanInput `json:"spans"`
16		Idempotency map[string]*IdempotencyRecord    `json:"idempotency"`
17	}
18	
19	func newState() *State {
20		return &State{
21			Spans:       map[string]map[string]*SpanInput{},
22			Idempotency: map[string]*IdempotencyRecord{},
23		}
24	}
25	
26	func (s *State) repair() {
27		if s.Spans == nil {
28			s.Spans = map[string]map[string]*SpanInput{}
29		}
30		for traceID, spans := range s.Spans {
31			if spans == nil {
32				s.Spans[traceID] = map[string]*SpanInput{}
33			}
34		}
35		if s.Idempotency == nil {
36			s.Idempotency = map[string]*IdempotencyRecord{}
37		}
38	}
39	
40	// traceIDs returns the stored trace ids in lexicographic order.
41	func (s *State) traceIDs() []string {
42		ids := make([]string, 0, len(s.Spans))
43		for id := range s.Spans {
44			ids = append(ids, id)
45		}
46		sortStrings(ids)
47		return ids
