135	// span renders one span JSON document. start, duration and the key order are
136	// fully explicit so every fixture is reproducible.
137	func span(traceID string, spanID string, parentID string, service string, operation string,
138		kind string, start string, durationNS int64, status string, spanCount *int) string {
139		document := map[string]any{
140			"trace_id":    traceID,
141			"span_id":     spanID,
142			"service":     service,
143			"operation":   operation,
144			"kind":        kind,
145			"start_time":  start,
146			"duration_ns": durationNS,
147			"status":      status,
148		}
149		if parentID == "" {
150			document["parent_id"] = nil
