182		auth := span("t-1", "s-auth", "s-root", "auth", "verify", "client", "2024-06-01T00:00:00.000000100Z", 200, "ok", nil)
183		db := span("t-1", "s-db", "s-root", "db", "select", "client", "2024-06-01T00:00:00.000000350Z", 600, "ok", nil)
184		query1 := span("t-1", "s-q1", "s-db", "db", "query", "internal", "2024-06-01T00:00:00.000000400Z", 200, "ok", nil)
