293	func TestSelfTimeIsDurationMinusChildDurations(t *testing.T) {
294		c := newClient(t)
295		c.loadFixture()
296		nodes := nodeByID(t, c.get("/traces/t-1"))
297	
298		wanted := map[string]int64{
299			"s-root": 400, // 1000 - 600 (the db subtree is the longest child)
300			"s-auth": 200,
301			"s-db":   350, // 600 - 250 (q2 is the longest child)
302			"s-q1":   200,
303			"s-q2":   250,
304			"s-pub":  50,
305		}
306		for spanID, want := range wanted {
307			if got := numberOf(t, nodes[spanID]["self_time_ns"]); got != want {
308				t.Errorf("self_time_ns of %s = %d, want %d", spanID, got, want)
309			}
310		}
311		// A leaf keeps its whole duration as self time, and every self time is >= 0.
312		for id, node := range nodes {
313			if self := numberOf(t, node["self_time_ns"]); self < 0 {
314				t.Errorf("self_time_ns of %s is negative: %d", id, self)
315			}
316		}
317		// self_time is the share of a span's duration that its single longest child
318		// does not cover, so self_time plus the longest child's subtree duration is
319		// the span duration exactly. This is what lets the critical path add up to
320		// the root duration.
321		for _, node := range nodes {
322			longest := int64(0)
323			for _, child := range listOf(t, node["children"]) {
324				if subtree := numberOf(t, objectOf(t, child)["subtree_duration_ns"]); subtree > longest {
325					longest = subtree
326				}
327			}
328			if got, want := numberOf(t, node["self_time_ns"])+longest, numberOf(t, node["duration_ns"]); got != want {
329				t.Errorf("span %v: self_time plus longest child subtree = %d, want its duration %d", node["span_id"], got, want)
330			}
331		}
