334	func TestCriticalPathEqualsRootDuration(t *testing.T) {
335		c := newClient(t)
336		c.loadFixture()
337		path := c.get("/traces/t-1/critical-path")
338	
339		ids := []string{}
340		for _, step := range listOf(t, path["path"]) {
341			object := objectOf(t, step)
342			id, _ := object["span_id"].(string)
343			ids = append(ids, id)
344		}
345		// The db branch carries the most exclusive time: 400 (root) + 350 (db) + 250 (q2).
346		wanted := []string{"s-root", "s-db", "s-q2"}
347		if !reflect.DeepEqual(ids, wanted) {
348			t.Fatalf("critical path %v, want %v", ids, wanted)
349		}
350		if got, want := numberOf(t, path["length_ns"]), numberOf(t, path["trace_duration_ns"]); got != want {
351			t.Fatalf("critical path length %d, want root duration %d", got, want)
352		}
353		if valid, _ := path["valid"].(bool); !valid {
354			t.Fatalf("critical path of a valid trace should be valid")
355		}
356		if path["method"] == "" {
357			t.Fatalf("the critical path must document its algorithm")
358		}
359		// Every hop of the path must contribute its own self_time.
360		total := int64(0)
361		for _, step := range listOf(t, path["path"]) {
362			total += numberOf(t, objectOf(t, step)["self_time_ns"])
363		}
364		if total != numberOf(t, path["length_ns"]) {
365			t.Fatalf("path self times sum to %d, length_ns is %v", total, path["length_ns"])
366		}
367	}
