369	// TestCriticalPathAlwaysEqualsRootDuration checks the headline invariant on
370	// several shapes: whatever the trace looks like, the longest self_time-weighted
371	// root-to-leaf path must add up to exactly the root duration.
372	func TestCriticalPathAlwaysEqualsRootDuration(t *testing.T) {
373		cases := []struct {
374			name      string
375			rootSpan  string
376			extraSpan []string
377		}{
378			{
379				name:     "single leaf",
380				rootSpan: span("t-leaf", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(1)),
381			},
382			{
383				name:     "chain",
384				rootSpan: span("t-chain", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(3)),
385				extraSpan: []string{
386					span("t-chain", "a", "root", "svc", "op", "internal", traceFixtureTime, 90, "ok", nil),
387					span("t-chain", "b", "a", "svc", "op", "internal", traceFixtureTime, 50, "ok", nil),
388				},
389			},
390			{
391				name:     "side branches",
392				rootSpan: span("t-branch", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(3)),
393				extraSpan: []string{
