432	// TestCriticalPathTieBreaksAreDeterministic pins the ranking of the critical
433	// path on a branched trace and the determinism of equal branches.
434	func TestCriticalPathTieBreaksAreDeterministic(t *testing.T) {
435		c := newClient(t)
436		root := span("t-2", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(4))
437		// Non-overlapping siblings, in start order: a 10–50, c 50–60, b 60–90. a is the
438		// longest chain below the root, so it carries the critical path and the root
439		// keeps the rest of its duration as exclusive time.
440		left := span("t-2", "a", "root", "svc", "op", "internal", "2024-06-01T00:00:00.000000010Z", 40, "ok", nil)
441		right := span("t-2", "b", "root", "svc", "op", "internal", "2024-06-01T00:00:00.000000060Z", 30, "ok", nil)
442		tail := span("t-2", "c", "root", "svc", "op", "internal", "2024-06-01T00:00:00.000000050Z", 10, "ok", nil)
443		c.post(root)
444		c.post(tail)
445		c.post(left)
446		c.post(right)
447	
448		path := c.get("/traces/t-2/critical-path")
449		ids := []string{}
450		for _, step := range listOf(t, path["path"]) {
451			id, _ := objectOf(t, step)["span_id"].(string)
452			ids = append(ids, id)
453		}
454		if !reflect.DeepEqual(ids, []string{"root", "a"}) {
455			t.Fatalf("the longest chain must carry the critical path, got %v", ids)
456		}
457		if got, want := numberOf(t, path["length_ns"]), int64(100); got != want {
458			t.Fatalf("length %d != root duration %d", got, want)
459		}
460		if got, want := numberOf(t, nodeByID(t, c.get("/traces/t-2"))["root"]["self_time_ns"]), int64(60); got != want {
461			t.Fatalf("root self time %d, want 100 - 40", got)
462		}
463	
464		// Without a dominating child the tie is decided by span ids, so the same
465		// input always yields the same path.
466		c.post(span("t-3", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(3)))
467		first := c.post(span("t-3", "b", "root", "svc", "op", "internal", "2024-06-01T00:00:00.000000060Z", 30, "ok", nil))
468		c.post(span("t-3", "a", "root", "svc", "op", "internal", "2024-06-01T00:00:00.000000010Z", 40, "ok", nil))
469		c.post(span("t-3", "z", "root", "svc", "op", "internal", "2024-06-01T00:00:00.000000070Z", 30, "ok", nil))
470		if complete, _ := first["complete"].(bool); complete {
471			t.Fatalf("the trace is not complete until its last span arrives")
472		}
473		tied := c.get("/traces/t-3/critical-path")
474		tiedIDs := []string{}
475		for _, step := range listOf(t, tied["path"]) {
476			id, _ := objectOf(t, step)["span_id"].(string)
477			tiedIDs = append(tiedIDs, id)
478		}
479		if !reflect.DeepEqual(tiedIDs, []string{"root", "a"}) {
480			t.Fatalf("a tie must be broken by the smallest span id sequence, got %v", tiedIDs)
481		}
482		if got, want := numberOf(t, tied["length_ns"]), int64(100); got != want {
483			t.Fatalf("length %d != root duration %d", got, want)
484		}
485		// t-2 has one dominating child (a, 40 ns), so the root keeps 100 - 40.
486		nodes := nodeByID(t, c.get("/traces/t-2"))
487		if got := numberOf(t, nodes["root"]["self_time_ns"]); got != 60 {
488			t.Fatalf("root self time %d, want 100 - 40", got)
489		}
490		for _, id := range []string{"a", "b", "c"} {
491			if got, want := numberOf(t, nodes[id]["self_time_ns"]), numberOf(t, nodes[id]["duration_ns"]); got != want {
492				t.Fatalf("leaf %s self time %d != duration %d", id, got, want)
493			}
494		}
495	}
