849		if overlap["span_id"] != "a" {
850			t.Fatalf("the overlap must name the earlier sibling: %v", overlap)
851		}
852		if message, _ := overlap["message"].(string); !bytes.Contains([]byte(message), []byte("overlap")) &&
853			!bytes.Contains([]byte(message), []byte("before sibling")) {
854			t.Fatalf("unexpected message %q", message)
855		}
856		// The rejected trace makes the critical path refuse to claim validity.
857		path := c.get("/traces/t-1/critical-path")
858		if valid, _ := path["valid"].(bool); valid {
859			t.Fatalf("a trace with overlapping siblings must not be valid")
860		}
861	}
