865		c.post(span("t-1", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(3)))
866		c.post(span("t-1", "a", "root", "svc", "op", "internal", traceFixtureTime, 30, "ok", nil))
867		c.post(span("t-1", "b", "root", "svc", "op", "internal",
868			"2024-06-01T00:00:00.000000030Z", 70, "ok", nil))
869	
870		trace := c.get("/traces/t-1")
871		if valid, _ := trace["valid"].(bool); !valid {
872			t.Fatalf("contiguous siblings must be accepted: %v", trace["violations"])
873		}
874		nodes := nodeByID(t, trace)
875		// The longest child subtree is b (70), so the root keeps 30 of its duration.
876		if got := numberOf(t, nodes["root"]["self_time_ns"]); got != 30 {
