1018	func TestSpanCountRulesAtIngestion(t *testing.T) {
1019		c := newClient(t)
1020		c.post(span("t-1", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(2)))
1021		c.post(span("t-1", "a", "root", "svc", "op", "internal", traceFixtureTime, 10, "ok", nil))
1022		// span_count is only allowed on a root span.
1023		c.reject(span("t-1", "b", "root", "svc", "op", "internal",
1024			"2024-06-01T00:00:00.000000020Z", 10, "ok", count(2)), http.StatusBadRequest)
1025		// A root span without span_count cannot be sized.
1026		c.reject(span("t-1", "root2", "", "svc", "op", "server", traceFixtureTime, 100, "ok", nil),
1027			http.StatusBadRequest)
