1035	// TestTimeContainmentViolationIsReportedNotRejected reaches a stored containment
1036	// violation through a grandchild that was ingested while its parent was still
1037	// missing: the check can only run against spans that already exist.
1038	func TestTimeContainmentViolationIsReportedNotRejected(t *testing.T) {
1039		c := newClient(t)
1040		// 30..90 fits inside 0..100, so ingestion accepts it while its parent is
1041		// still missing; the check can only run against spans that already exist.
1042		c.post(span("t-1", "root", "", "svc", "op", "server", traceFixtureTime, 100, "ok", count(3)))
1043		c.post(span("t-1", "gchild", "child", "svc", "op", "internal",
1044			"2024-06-01T00:00:00.000000030Z", 60, "ok", nil))
1045		c.post(span("t-1", "child", "root", "svc", "op", "internal", traceFixtureTime, 60, "ok", nil))
1046	
1047		// The grandchild now overhangs its parent: 30..90 is not inside 0..60.
1048		status, raw, decoded := c.do(request{method: http.MethodGet, path: "/traces/t-1"})
1049		if status != http.StatusConflict {
