1053		violations := listOf(t, cause["violations"])
1054		if len(violations) != 1 {
1055			t.Fatalf("the overhang is the only violation, got %s", raw)
1056		}
1057		containment := objectOf(t, violations[0])
1058		if containment["code"] != "time_not_contained" {
1059			t.Fatalf("violation %v", containment)
1060		}
1061		if containment["span_id"] != "gchild" {
1062			t.Fatalf("violation must name the offending span: %v", containment)
1063		}
1064		message, _ := containment["message"].(string)
1065		if !bytes.Contains([]byte(message), []byte("not contained in parent")) {
1066			t.Fatalf("unexpected message %q", message)
1067		}
1068		// A stored span that breaks containment makes the trace unusable, so the
1069		// critical path refuses to claim validity for it.
1070		path := c.get("/traces/t-1/critical-path")
1071		if valid, _ := path["valid"].(bool); valid {
