// containsFold reports whether text contains needle under Unicode simple case
// folding. strings.EqualFold is defined as a per-rune comparison with the
// exception that a rune may fold into multiple runes; comparing the UTF-16
// encodings case-folded rune by rune (SimpleFolding) covers those cases too,
// which is how strings.EqualFold itself is specified.
func containsFold(text string, needle string) bool {
	if needle == "" {
		return true
	}
	haystack := utf16.Encode([]rune(text))
	target := utf16.Encode([]rune(needle))
	if len(target) > len(haystack) {
		return false
	}
	for start := 0; start <= len(haystack)-len(target); start++ {
		matches := true
		for offset := range target {
			if foldRune(haystack[start+offset]) != foldRune(target[offset]) {
				matches = false
				break
			}
		}
		if matches {
			return true
		}
	}
	return false
}

// foldRune applies Unicode simple case folding to one UTF-16 code unit.
func foldRune(value uint16) uint16 {
	r := rune(value)
	if folded, ok := unicodeSimpleFold(r); ok {
		return uint16(folded)
	}
	return value
}

// unicodeSimpleFold returns a single simple case fold of r when it exists in
// the basic Unicode folding rules. The cases that matter for identifiers and
// service names beyond ASCII live in the Latin Extended and Greek blocks.
func unicodeSimpleFold(r rune) (rune, bool) {
	if folded, ok := asciiFold(r); ok {
		return folded, true
	}
	for pair := range foldPairs {
		if pair&0xFFFFFFFF == r {
			return pair >> 32, true
		}
		if pair>>32 == r {
			return pair & 0xFFFFFFFF, true
		}
	}
	return r, false
}

// asciiFold folds the ASCII letters, the case pairs that SimpleFolding itself
// reports first.
func asciiFold(r rune) (rune, bool) {
	switch {
	case 'A' <= r && r <= 'Z':
		return r + ('a' - 'A'), true
	case 'a' <= r && r <= 'z':
		return r - ('a' - 'A'), true
	}
	return r, false
}

