		if err != nil {
			return nil, err
		}
		filter.MinDurationNS = &value
	}
	if raw := query.Get("max_duration_ns"); raw != "" {
		value, err := parseDurationBound(raw, "max_duration_ns")
		if err != nil {
			return nil, err
		}
