func referenceContainsFold(text, needle string) bool {
	if needle == "" {
		return true
	}
	tRunes := []rune(text)
	n := len([]rune(needle))
	for i := 0; i+n <= len(tRunes); i++ {
		if strings.EqualFold(string(tRunes[i:i+n]), needle) {
			return true
		}
	}
	return false
}

func TestContainsFoldMatchesReference(t *testing.T) {
	// Build a sample alphabet: ASCII, Latin-1, Latin Extended A/B, Greek, and
	// every rune that belongs to a SimpleFold orbit of size > 1 below U+03000.
	sample := []rune{'a', 'B', 'z', '0', '-', '/', 'é', 'É', 'ß', 'ẞ', 'ı', 'ſ', 'K', 'Å', 'Ω', 'ω'}
	for r := rune(0x80); r < 0x3000; r++ {
		if unicode.SimpleFold(r) != r {
			sample = append(sample, r)
		}
	}
	words := make([]string, 0, len(sample))
	for _, r := range sample {
		words = append(words, string([]rune{r, 'x', r}))
	}
	needles := append([]string{}, words...)
	needles = append(needles, "x", "", "X", "aB", "éXÉ", "k", "ı")
	for i, w := range words {
		for j, n := range needles {
			got := containsFold(w, n)
			want := referenceContainsFold(w, n)
			if got != want {
				t.Fatalf("word#%d needle#%d containsFold(%q,%q)=%v want %v", i, j, w, n, got, want)
			}
		}
	}
}
